"use client";

import React from "react";

export default function Usage() {
	return (
		<div className="relative w-full flex items-center justify-center"></div>
	);
}

"use client";

import React, { useEffect, useMemo, useState, type CSSProperties } from "react";

import Image from "next/image";

import { cn } from "@/lib/utils";
import { cva, type VariantProps } from "class-variance-authority";

// Credit:
// https://www.cult-ui.com/docs/components/text-gif

// Define text style variants
const textBaseVariants = cva("", {
	variants: {
		size: {
			default: "text-2xl sm:text-3xl lg:text-4xl",
			xxs: "text-base sm:text-lg lg:text-lg",
			xs: "text-lg sm:text-xl lg:text-2xl",
			sm: "text-xl sm:text-2xl lg:text-3xl",
			md: "text-2xl sm:text-3xl lg:text-4xl",
			lg: "text-3xl sm:text-4xl lg:text-5xl",
			xl: "text-4xl sm:text-5xl lg:text-6xl",
			xxl: "text-[2.5rem] sm:text-6xl lg:text-[6rem]",
			xll: "text-5xl sm:text-6xl lg:text-[7rem]",
			xxxl: "text-[6rem] leading-5 lg:leading-8 sm:text-6xl lg:text-[8rem]",
		},
		weight: {
			default: "font-bold",
			thin: "font-thin",
			base: "font-base",
			semi: "font-semibold",
			bold: "font-bold",
			black: "font-black",
		},
		font: {
			default: "font-sansTight",
			serif: "font-serif",
			mono: "font-mono",
		},
	},
	defaultVariants: {
		size: "default",
		weight: "bold",
		font: "default",
	},
});

interface GifTextProps extends VariantProps<typeof textBaseVariants> {
	gifUrl: string;
	text: string;
	className?: string;
	fallbackColor?: string;
	transitionDuration?: number;
}

const GifText = React.memo(function GifTextComponent({
	gifUrl,
	text,
	size,
	weight,
	font,
	className,
	fallbackColor = "black",
	transitionDuration = 300,
}: GifTextProps) {
	const [loaded, setLoaded] = useState(false);
	const [error, setError] = useState(false);

	// Reset states when gifUrl changes
	useEffect(() => {
		setLoaded(false);
		setError(false);
	}, [gifUrl]);

	// Memoize className for performance
	const textClassName = useMemo(
		() =>
			cn(
				textBaseVariants({ size, weight, font }),
				loaded && !error ? "text-transparent bg-clip-text" : "",
				className,
				"pb-1.5 md:pb-4"
			),
		[size, weight, font, className, loaded, error]
	);

	// Memoize style for performance
	const textStyle = useMemo(() => {
		const style: CSSProperties = {
			backgroundSize: "cover",
			backgroundPosition: "center",
			backgroundRepeat: "no-repeat",
			WebkitBackgroundClip: "text",
			lineHeight: 1,
			textAlign: "center",
			color: fallbackColor, // Always set the fallback color initially
			WebkitTextFillColor: fallbackColor, // Safari fix
			transition: `background-image ${transitionDuration}ms ease-in-out, color ${transitionDuration}ms ease-in-out`,
		};

		if (loaded && !error) {
			style.backgroundImage = `url(${gifUrl})`;
			style.color = "transparent";
			style.WebkitTextFillColor = "transparent"; // Safari fix
		}

		return style;
	}, [loaded, error, gifUrl, transitionDuration, fallbackColor]);

	return (
		<div className="relative inline-block">
			{/* Hidden image for preloading */}
			{gifUrl && (
				<Image
					src={gifUrl || "/itjustworks.jpg"}
					alt=""
					width={1}
					height={1}
					className="absolute opacity-0 pointer-events-none"
					onLoad={() => {
						setLoaded(true);
						setError(false);
					}}
					onError={() => {
						setError(true);
						setLoaded(false);
					}}
					priority
					unoptimized
				/>
			)}
			<span className={textClassName} style={textStyle}>
				{text}
			</span>
		</div>
	);
});

// Export common GIF URLs
const gifUrls = [
	"https://media.giphy.com/media/3zvbrvbRe7wxBofOBI/giphy.gif",
	"https://media.giphy.com/media/fnglNFjBGiyAFtm6ke/giphy.gif",
	"https://media.giphy.com/media/9Pmfazv34l7aNIKK05/giphy.gif",
	"https://media.giphy.com/media/4bhs1boql4XVJgmm4H/giphy.gif",
];

// Optional: Preloader component
function PreloadGifs() {
	return (
		<div className="hidden">
			{gifUrls.map((url) => (
				<Image
					key={url}
					src={url}
					alt=""
					width={1}
					height={1}
					priority
					unoptimized
				/>
			))}
		</div>
	);
}

export { GifText };

import registry from "@/registry.json";
import { clsx, type ClassValue } from "clsx";
import type { RegistryItem } from "shadcn/registry";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const components = registry.items as unknown as RegistryItem[];

export const getComponents = (selectedTags: any[] = []): RegistryItem[] => {
	return selectedTags.length
		? components.filter((component) =>
				selectedTags.every(
					(tag) => component.meta?.tags?.includes(tag) ?? false
				)
			)
		: components;
};

export const getComponentsByNames = (names: string[]): RegistryItem[] => {
	const componentsMap = new Map(components.map((comp) => [comp.name, comp]));

	return names
		.map((name) => componentsMap.get(name))
		.filter((comp): comp is RegistryItem => comp !== undefined);
};

export const getAvailableTags = (selectedTags: any[]): any[] => {
	if (!selectedTags.length) return [];

	// Get all components that have all the selected tags
	const matchingComponents = components.filter((component) =>
		selectedTags.every((tag) => component.meta?.tags?.includes(tag) ?? false)
	);

	// Get all unique tags from the matching components
	const availableTags = new Set<any>();
	matchingComponents.forEach((component) => {
		component.meta?.tags?.forEach((tag: any) => {
			if (!selectedTags.includes(tag)) {
				availableTags.add(tag);
			}
		});
	});

	return Array.from(availableTags);
};

export const convertRegistryPaths = (content: string): string => {
	return content
		.replace(/@\/registry\/default\/ui/g, "@/components/ui")
		.replace(/@\/registry\/default\/compositions/g, "@/components")
		.replace(/@\/registry\/default\/hooks/g, "@/hooks")
		.replace(/@\/registry\/default\/lib/g, "@/lib");
};
